            font-size: 2rem;
            font-weight: 700;
            color: var(--accent);
        }

        .explanation-box {
            margin-top: 1rem;
            padding: 1rem;
            background: #fffbeb;
            border: 1px solid #fcd34d;
            border-radius: 8px;
